17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.time.LocalDate;
20	import java.util.Collection;
21	import java.util.List;
22	import java.util.Objects;
23	
24	import org.springframework.http.HttpHeaders;
25	import org.springframework.http.HttpStatus;
26	import org.springframework.http.ResponseEntity;
27	import org.springframework.samples.petclinic.mapper.OwnerMapper;
28	import org.springframework.samples.petclinic.mapper.PetMapper;
29	import org.springframework.samples.petclinic.mapper.VisitMapper;
30	import org.springframework.samples.petclinic.model.Owner;
31	import org.springframework.samples.petclinic.model.Pet;
32	import org.springframework.samples.petclinic.model.Visit;
33	import org.springframework.samples.petclinic.rest.api.OwnersApi;
34	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
35	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
36	import org.springframework.samples.petclinic.rest.dto.PetDto;
37	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
38	import org.springframework.samples.petclinic.rest.dto.VisitDto;
39	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
40	import org.springframework.samples.petclinic.service.ClinicService;
41	import org.springframework.security.access.prepost.PreAuthorize;
42	import org.springframework.web.bind.annotation.CrossOrigin;
43	import org.springframework.web.bind.annotation.RequestMapping;
44	import org.springframework.web.bind.annotation.RestController;
45	import org.springframework.web.util.UriComponentsBuilder;
46	
47	import jakarta.transaction.Transactional;
48	
49	/**
50	 * @author Vitaliy Fedoriv
51	 */
52	
53	@RestController
54	@CrossOrigin(exposedHeaders = "errors, content-type")
55	@RequestMapping("/api")
56	public class OwnerRestControllerV1 implements OwnersApi {
57	
58	    private final ClinicService clinicService;
59	
60	    private final OwnerMapper ownerMapper;
61	
62	    private final PetMapper petMapper;
63	
64	    private final VisitMapper visitMapper;
65	
66	    public OwnerRestControllerV1(ClinicService clinicService,
67	                                 OwnerMapper ownerMapper,
68	                                 PetMapper petMapper,
69	                                 VisitMapper visitMapper) {
70	        this.clinicService = clinicService;
71	        this.ownerMapper = ownerMapper;
72	        this.petMapper = petMapper;
73	        this.visitMapper = visitMapper;
74	    }
75	
76	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
77	    @Override
78	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
79	        Collection<Owner> owners;
80	        if (lastName != null) {
81	            owners = this.clinicService.findOwnerByLastName(lastName);
82	        } else {
83	            owners = this.clinicService.findAllOwners();
84	        }
85	        if (owners.isEmpty()) {
86	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
87	        }
88	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
89	    }
90	
91	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
92	    @Override
93	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
94	        Owner owner = this.clinicService.findOwnerById(ownerId);
95	        if (owner == null) {
96	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
97	        }
98	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
99	    }
100	
101	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
102	    @Override
103	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
104	        HttpHeaders headers = new HttpHeaders();
105	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
106	        if (isDuplicateOwner(owner) || isDuplicateEmail(owner)) {
107	            return new ResponseEntity<>(HttpStatus.CONFLICT);
108	        }
109	        if (owner.getRegistrationDate() == null) {
110	            owner.setRegistrationDate(LocalDate.now());
111	        }
112	        owner.setMembershipNumber(this.clinicService.findAllOwners().size() + 1);
113	        owner.setCustomerCode(nextCustomerCode(owner.getCity()));
114	        this.clinicService.saveOwner(owner);
115	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
116	        headers.setLocation(UriComponentsBuilder.newInstance()
117	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
118	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
119	    }
120	
121	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
122	    @Override
123	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
124	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
125	        if (currentOwner == null) {
126	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
127	        }
128	        currentOwner.setAddress(ownerFieldsDto.getAddress());
129	        currentOwner.setCity(ownerFieldsDto.getCity());
130	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
131	        currentOwner.setLastName(ownerFieldsDto.getLastName());
132	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
133	        this.clinicService.saveOwner(currentOwner);
134	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
135	    }
136	
137	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
138	    @Transactional
139	    @Override
140	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
141	        Owner owner = this.clinicService.findOwnerById(ownerId);
142	        if (owner == null) {
143	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
144	        }
145	        this.clinicService.deleteOwner(owner);
146	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
147	    }
148	
149	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
150	    @Override
151	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
152	        Owner owner = this.clinicService.findOwnerById(ownerId);
153	        if (owner == null) {
154	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
155	        }
156	        HttpHeaders headers = new HttpHeaders();
157	        Pet pet = petMapper.toPet(petFieldsDto);
158	        owner.setId(ownerId);
159	        pet.setOwner(owner);
160	        pet.getType().setName(null);
161	        this.clinicService.savePet(pet);
162	        PetDto petDto = petMapper.toPetDto(pet);
163	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
164	            .buildAndExpand(pet.getId()).toUri());
165	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
166	    }
167	
168	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
169	    @Override
170	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
171	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
172	        if (currentOwner != null) {
173	            Pet currentPet = this.clinicService.findPetById(petId);
174	            if (currentPet != null) {
175	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
176	                currentPet.setName(petFieldsDto.getName());
177	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
178	                this.clinicService.savePet(currentPet);
179	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
180	            }
181	        }
182	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
183	    }
184	
185	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
186	    @Override
187	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
188	        HttpHeaders headers = new HttpHeaders();
189	        Visit visit = visitMapper.toVisit(visitFieldsDto);
190	        Pet pet = new Pet();
191	        pet.setId(petId);
192	        visit.setPet(pet);
193	        this.clinicService.saveVisit(visit);
194	        VisitDto visitDto = visitMapper.toVisitDto(visit);
195	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
196	            .buildAndExpand(visit.getId()).toUri());
197	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
198	    }
199	
200	
201	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
202	    @Override
203	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
204	        Owner owner = this.clinicService.findOwnerById(ownerId);
205	        if (owner != null) {
206	            Pet pet = owner.getPet(petId);
207	            if (pet != null) {
208	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
209	            }
210	        }
211	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
212	    }
213	
214	    /**
215	     * Builds the customer code for a newly created owner, formatted as
216	     * {@code '<UPPERCASE_CITY>-<NNNN>'} where {@code NNNN} is one more than the number of
217	     * owners already registered in that city, zero-padded to four digits (e.g.
218	     * {@code 'LONDON-0007'}). Cities are matched ignoring letter case so the sequence is
219	     * consistent with the upper-cased prefix.
220	     *
221	     * @param city the city of the owner being created
222	     * @return the assigned customer code
223	     */
224	    private String nextCustomerCode(String city) {
225	        long ownersInCity = this.clinicService.findAllOwners().stream()
226	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
227	            .count();
228	        return city.toUpperCase() + "-" + String.format("%04d", ownersInCity + 1);
229	    }
230	
231	    /**
232	     * Determines whether an owner already exists that uses the same telephone number as the
233	     * given candidate. The comparison ignores letter case and surrounding or repeated
234	     * whitespace.
235	     *
236	     * @param owner the candidate owner to check
237	     * @return {@code true} if an owner with the same telephone number already exists
238	     */
239	    private boolean isDuplicateOwner(Owner owner) {
240	        String telephone = normalize(owner.getTelephone());
241	        return this.clinicService.findAllOwners().stream()
242	            .anyMatch(existing -> Objects.equals(normalize(existing.getTelephone()), telephone));
243	    }
244	
245	    /**
246	     * Determines whether an owner already exists that uses the same email address as the
247	     * given candidate. Owners without an email address are never considered duplicates.
248	     * The comparison ignores letter case and surrounding or repeated whitespace.
249	     *
250	     * @param owner the candidate owner to check
251	     * @return {@code true} if an owner with the same email address already exists
252	     */
253	    private boolean isDuplicateEmail(Owner owner) {
254	        String email = normalize(owner.getEmail());
255	        if (email == null || email.isEmpty()) {
256	            return false;
257	        }
258	        return this.clinicService.findAllOwners().stream()
259	            .anyMatch(existing -> Objects.equals(normalize(existing.getEmail()), email));
260	    }
261	
262	    /**
263	     * Normalizes a value for duplicate detection so that comparisons ignore letter case and
264	     * surrounding or repeated whitespace. Leading and trailing whitespace is stripped, any run
265	     * of internal whitespace collapses to a single space, and the result is lower-cased. For
266	     * example {@code "  John   Smith "} and {@code "John Smith"} both normalize to
267	     * {@code "john smith"}.
268	     *
269	     * @param value the value to normalize, may be {@code null}
270	     * @return the normalized value, or {@code null} if {@code value} is {@code null}
271	     */
272	    private static String normalize(String value) {
273	        if (value == null) {
274	            return null;
275	        }
276	        return value.strip().replaceAll("\\s+", " ").toLowerCase();
277	    }
278	}
